describe('Icon Button Accessibility - Accessible Names', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should have accessible names for all icon buttons', () => {
    cy.get('button[class*="icon"]').each(($button) => {
      cy.wrap($button).should(($el) => {
        const ariaLabel = $el.attr('aria-label');
        const ariaLabelledBy = $el.attr('aria-labelledby');
        const title = $el.attr('title');
        const textContent = $el.text().trim();

        const hasAccessibleName = ariaLabel || ariaLabelledBy || title || textContent;
        expect(hasAccessibleName).to.be.ok;
      });
    });
  });

  it('should have aria-label for icon buttons without visible text', () => {
    cy.get('button[class*="icon"]').each(($button) => {
      const textContent = $button.text().trim();

      if (!textContent) {
        cy.wrap($button).should(($el) => {
          const ariaLabel = $el.attr('aria-label');
          const ariaLabelledBy = $el.attr('aria-labelledby');
          const title = $el.attr('title');

          const hasAccessibleName = ariaLabel || ariaLabelledBy || title;
          expect(hasAccessibleName).to.be.ok;
        });
      }
    });
  });

  it('should have non-empty accessible names', () => {
    cy.get('button[class*="icon"]').each(($button) => {
      cy.wrap($button).should(($el) => {
        const ariaLabel = $el.attr('aria-label');
        const title = $el.attr('title');
        const textContent = $el.text().trim();

        if (ariaLabel) {
          expect(ariaLabel.length).to.be.greaterThan(0);
        }
        if (title) {
          expect(title.length).to.be.greaterThan(0);
        }
        if (!ariaLabel && !title) {
          expect(textContent.length).to.be.greaterThan(0);
        }
      });
    });
  });

  it('should pass axe accessibility checks for icon buttons', () => {
    cy.injectAxe();
    cy.get('button[class*="icon"]').each(($button) => {
      cy.wrap($button).checkA11y(null, {
        rules: {
          'button-name': { enabled: true }
        }
      });
    });
  });
});
